/// <summary>
/// Extension of Tax
/// </summary>
[ExtensionOf(classStr(Tax))]
final class METTax_Extension
{
    private boolean metExcludeBasedOnLandedCostCalcFlag; // MPJ_26540_PriceSimulatorChanges

}

Method.Source:
/// <summary>
/// MPJ_26540_PriceSimulatorChanges
/// Get/set metExcludeBasedOnLandedCostCalcFlag. Optionally exclude
/// tax codes where landed cost exclusion flag set.
/// </summary>
/// <param name = "_metExcludeBasedOnLandedCostCalcFlag">_metExcludeBasedOnLandedCostCalcFlag</param>
/// <returns>metExcludeBasedOnLandedCostCalcFlag</returns>
public boolean parmMetExcludeBasedOnLandedCostCalcFlag(boolean _metExcludeBasedOnLandedCostCalcFlag = metExcludeBasedOnLandedCostCalcFlag)
{
    metExcludeBasedOnLandedCostCalcFlag = _metExcludeBasedOnLandedCostCalcFlag;
    return metExcludeBasedOnLandedCostCalcFlag;
}

    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_tmpTax">_tmpTax</param>
    /// <param name = "_taxOnTaxBasedOnInvoiceTotalCalculation">_taxOnTaxBasedOnInvoiceTotalCalculation</param>
    /// <returns>Result</returns>
    TaxAmount calcTax(
        TmpTax          _tmpTax, 
        boolean         _taxOnTaxBasedOnInvoiceTotalCalculation)
    {
        TmpTax tmpTaxAdjusted;
        tmpTaxAdjusted.setTmpData(_tmpTax);

        if(this.parmMetExcludeBasedOnLandedCostCalcFlag())
        {
            ttsbegin;
            while select forupdate tmpTaxAdjusted
            {
                if(TaxTable::find(tmpTaxAdjusted.TaxCode).METExcludeFromLandedCostCalc)
                {
                    tmpTaxAdjusted.delete();
                }
            }
            ttscommit;
        }

        TaxAmount amount = next calcTax(tmpTaxAdjusted, _taxOnTaxBasedOnInvoiceTotalCalculation);
        return amount;
    }
